677→    // =========================================================================
678→    // Bitmask helpers
679→    // =========================================================================
680→
681→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
682→            int offset) {
683→        for (int i = 0; i < fields.size(); i++) {
684→            if (values[i] == null) {
685→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
686→            }
687→        }
688→    }
689→
690→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
691→            int offset) {
692→        int boolIdx = 0;
693→        for (int i = 0; i < fields.size(); i++) {
694→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
695→                final Object val = values[i];
696→                if (val instanceof Boolean b && b) {
697→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
698→                }
699→                boolIdx++;
700→            }
701→        }
702→    }
703→
704→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
705→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
706→    }
707→
708→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
709→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
710→    }
711→
712→    private static int countBoolFields(List<FieldDefinition> fields) {
713→        int count = 0;
714→        for (final FieldDefinition fd : fields) {
715→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
716→                count++;
717→            }
718→        }
719→        return count;
720→    }
721→
722→    private static int countBoolFieldsUpTo(List<FieldDefinition> fields, int limit) {
723→        int count = 0;
724→        final int bound = Math.min(limit, fields.size());
725→        for (int i = 0; i < bound; i++) {
726→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
727→                count++;
728→            }
729→        }
730→        return count;
731→    }
732→
733→    // =========================================================================
734→    // VarInt (LEB128 unsigned)
735→    // =========================================================================
736→
737→    private static int varIntSize(int value) {
738→        assert value >= 0 : "VarInt value must be non-negative";
739→        if (value < 128) {
740→            return 1;
741→        }
742→        if (value < 16384) {
743→            return 2;
744→        }
745→        if (value < 2097152) {
746→            return 3;
747→        }
748→        if (value < 268435456) {
749→            return 4;
750→        }
751→        return 5;
752→    }
753→
754→    private static void writeVarInt(Cursor c, int value) {
755→        assert value >= 0 : "VarInt value must be non-negative";
756→        while (true) {
757→            if ((value & ~0x7F) == 0) {
758→                c.buf[c.pos++] = (byte) value;
759→                return;
760→            }
761→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
762→            value >>>= 7;
763→        }
764→    }
765→
766→    private static int readVarInt(byte[] buf, Cursor cursor) {
767→        int result = 0;
768→        int shift = 0;
769→        while (true) {
770→            final byte b = buf[cursor.pos++];
771→            result |= (b & 0x7F) << shift;
772→            if ((b & 0x80) == 0) {
773→                break;
774→            }
775→            shift += 7;
776→            assert shift <= 35 : "VarInt overflow — corrupt data";
777→        }
778→        return result;
779→    }
780→
781→    // =========================================================================
782→    // Primitive I/O
783→    // =========================================================================
784→
785→    private static void writeShortBE(byte[] buf, int offset, short value) {
786→        buf[offset] = (byte) (value >> 8);
787→        buf[offset + 1] = (byte) value;
788→    }
789→
790→    private static short readShortBE(byte[] buf, int offset) {
791→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
792→    }
793→
794→    private static void writeIntBE(byte[] buf, int offset, int value) {
795→        buf[offset] = (byte) (value >> 24);
796→        buf[offset + 1] = (byte) (value >> 16);
797→        buf[offset + 2] = (byte) (value >> 8);
798→        buf[offset + 3] = (byte) value;
799→    }
800→
801→    private static int readIntBE(byte[] buf, int offset) {
802→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
803→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
804→    }
805→
806→    private static void writeLongBE(byte[] buf, int offset, long value) {
807→        buf[offset] = (byte) (value >> 56);
808→        buf[offset + 1] = (byte) (value >> 48);
809→        buf[offset + 2] = (byte) (value >> 40);
810→        buf[offset + 3] = (byte) (value >> 32);
811→        buf[offset + 4] = (byte) (value >> 24);
812→        buf[offset + 5] = (byte) (value >> 16);
813→        buf[offset + 6] = (byte) (value >> 8);
814→        buf[offset + 7] = (byte) value;
815→    }
816→
817→    private static long readLongBE(byte[] buf, int offset) {
818→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
819→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
820→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
821→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
822→    }
823→
824→    // =========================================================================
825→    // Cursor
826→    // =========================================================================
827→
828→    /** Mutable position cursor for sequential byte-array I/O. */
829→    private static final class Cursor {
830→
831→        final byte[] buf;
832→        int pos;
833→
834→        Cursor(byte[] buf, int pos) {
835→            this.buf = buf;
836→            this.pos = pos;
837→        }
838→
839→        /** Advances position by {@code n} bytes and returns the old position. */
840→        int advance(int n) {
841→            final int old = pos;
842→            pos += n;
843→            return old;
844→        }
845→    }
846→}
